-- 显示统计信息
SELECT 
  category as '商品分类',
  COUNT(*) as '商品数量',
  MIN(price) as '最低价格',
  MAX(price) as '最高价格',
  AVG(price) as '平均价格',
  SUM(sales) as '总销量'
FROM products
WHERE merchant_id = 4
GROUP BY category;

